def count_components_4conn(grid, target):
    h, w = len(grid), len(grid[0])
    visited = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == target and (r,c) not in visited:
                comp = []
                stk = [(r,c)]
                while stk:
                    cr, cc = stk.pop()
                    if (cr,cc) in visited: continue
                    visited.add((cr,cc))
                    comp.append((cr,cc))
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr,nc = cr+dr, cc+dc
                        if 0<=nr<h and 0<=nc<w and grid[nr][nc]==target and (nr,nc) not in visited:
                            stk.append((nr,nc))
                comps.append(comp)
    return comps

